import PropTypes from "prop-types";
import React from "react";

import * as style from "./StaticLinkText.styles";

class StaticLinkText extends React.Component {
  constructor(props) {
    super(props);
  }

  render() {
    const { color, text, onClick } = this.props;
    return (
      <button className={style.button} onClick={onClick} style={{ color }}>
        {text}
      </button>
    );
  }
}

StaticLinkText.propTypes = {
  text: PropTypes.string.isRequired,
  color: PropTypes.string,
  background: PropTypes.string,
  onClick: PropTypes.func.isRequired,
};

export default StaticLinkText;
